using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Polarity.Config;using Polarity.Entities;using Codely.Newtonsoft.Json;using Object=UnityEngine.Object;
var path="Assets/Polarity/Prefabs/Levels/02-Contact.prefab";var root=PrefabUtility.LoadPrefabContents(path);try{var room=root.GetComponent<LevelRoom>();room.Player.transform.localPosition=new Vector3(2,1,0);var bodies=room.CopyBodies();var positions=new[]{new Vector3(-3.3f,.1f,0),new Vector3(-4.5f,.5f,0),new Vector3(-4.9f,-.9f,0),new Vector3(.5f,-.6f,0)};for(int i=0;i<4;i++){bodies[i].transform.localPosition=positions[i];var so=new SerializedObject(bodies[i]);so.FindProperty("initialPolarity").enumValueIndex=(int)(i==3?Polarity.Model.Polarity.Negative:Polarity.Model.Polarity.Neutral);so.ApplyModifiedPropertiesWithoutUndo();if(i<3){var hs=new SerializedObject(bodies[i].GetComponent<Health>());hs.FindProperty("maxHealth").intValue=2;hs.ApplyModifiedPropertiesWithoutUndo();}}
var hazards=root.GetComponentsInChildren<SpikeHazard>(true);var spike=hazards.First();foreach(var other in hazards.Skip(1))Object.DestroyImmediate(other.gameObject);spike.name="Spikes_Exit";spike.transform.localPosition=new Vector3(-.7f,-3,0);spike.GetComponent<BoxCollider2D>().size=new Vector2(3.2f,.8f);foreach(var sr in spike.GetComponentsInChildren<SpriteRenderer>())sr.transform.localScale=new Vector3(3.2f,.8f,1);
var template=root.GetComponentsInChildren<BoxCollider2D>().First(c=>c.name=="Wall_Top").gameObject;var faces=new System.Collections.Generic.List<SpriteRenderer>();foreach(float y in new[]{1.8f,-1.8f}){var wall=Object.Instantiate(template,template.transform.parent);wall.name=y>0?"Wall_ChannelTop":"Wall_ChannelBottom";wall.transform.localPosition=new Vector3(-4,y,0);wall.transform.localScale=Vector3.one;wall.GetComponent<BoxCollider2D>().size=new Vector2(4,.4f);var ground=wall.transform.Find("GroundFootprint");ground.localScale=new Vector3(4,.4f,1);var visual=wall.transform.Find("VisualRoot");visual.localScale=Vector3.one;foreach(var sr in visual.GetComponentsInChildren<SpriteRenderer>()){if(sr.name=="FrontFace"){sr.transform.localScale=new Vector3(4,.55f,1);sr.transform.localPosition=new Vector3(0,.075f,0);}else if(sr.name=="TopFace"){sr.transform.localScale=new Vector3(4,.4f,1);sr.transform.localPosition=new Vector3(0,.55f,0);}else{sr.transform.localScale=new Vector3(4,.04f,1);sr.transform.localPosition=new Vector3(0,.73f,0);}faces.Add(sr);}}
var rs=new SerializedObject(room);var oc=rs.FindProperty("occludingSprites");for(int i=oc.arraySize-1;i>=0;i--)if(oc.GetArrayElementAtIndex(i).objectReferenceValue==null)oc.DeleteArrayElementAtIndex(i);foreach(var sr in faces){int n=oc.arraySize;oc.InsertArrayElementAtIndex(n);oc.GetArrayElementAtIndex(n).objectReferenceValue=sr;}rs.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}var def=AssetDatabase.LoadAssetAtPath<LevelDefinition>("Assets/Polarity/Configs/Levels/02-Contact.asset");var ds=new SerializedObject(def);ds.FindProperty("title").stringValue="接触扩散";ds.FindProperty("markBudget").intValue=3;ds.FindProperty("teachingHint").stringValue="真实接触才会免费传播；已有极性不会被覆盖。换个站位，尝试让分开的敌人再次汇合，借箱子与尖刺清场。空格慢速，R 重试。";ds.ApplyModifiedPropertiesWithoutUndo();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());return "02 seed saved: budget3, 3 neutral enemies2HP, negative crate, local exit spikes, 2 short walls.";

