using System;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Polarity.Config;using Polarity.Controllers;using Polarity.Entities;using Polarity.Model;using Polarity.Simulation;using Polarity.Views;using Polarity.Debugging;using Codely.Newtonsoft.Json;using Object=UnityEngine.Object;
var flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;EditorApplication.isPaused=true;
async Task<SimulationWorld> Load(int index=1){var old=Object.FindObjectOfType<SimulationWorld>();typeof(LevelController).GetField("<CurrentLevelIndex>k__BackingField",flags).SetValue(old.Level,index);var done=new TaskCompletionSource<SimulationWorld>();UnityEngine.Events.UnityAction<Scene,LoadSceneMode> cb=null;cb=(s,m)=>{SceneManager.sceneLoaded-=cb;EditorApplication.isPaused=true;done.SetResult(Object.FindObjectOfType<SimulationWorld>());};SceneManager.sceneLoaded+=cb;EditorApplication.isPaused=false;if(!old.Level.RequestRestart())throw new Exception("restart rejected");return await done.Task;}
var stepMethod=typeof(SimulationWorld).GetMethod("FixedUpdate",flags);void Step(SimulationWorld w)=>stepMethod.Invoke(w,null);float[] V(Vector2 p)=>new[]{p.x,p.y};
void Walk(SimulationWorld w,Vector2 to){Vector2 d=to-w.Player.Rigidbody.position;w.Player.SampleMoveInput(d.y>.12f,d.x<-.12f,d.y<-.12f,d.x>.12f);}
async Task<object> Case(string name,int source,int markAt,int flipAt,Vector2[] destinations,int[] switchAt,int recolor=4,int thirdAt=-1,int thirdTarget=1){var w=await Load();var actors=w.Bodies.ToArray();var marks=new List<object>();var spread=new List<object>();var hits=new List<object>();var traces=new List<object>();var contactChanges=new List<object>();string lastPairs="";
w.MarkResolved+=r=>marks.Add(new{step=w.CompletedStepCount+1,time=w.SimulationTime+.02,r.Request.TargetId,polarity=r.Request.Polarity.ToString(),outcome=r.Outcome.ToString(),budget=w.State.RemainingMarks});w.PropagationCommitted+=r=>spread.Add(new{r.Step,time=w.SimulationTime,r.SourceId,r.TargetId,polarity=r.Polarity.ToString(),r.NormalImpulse,p=V(w.Player.Rigidbody.position),source=V(r.SourcePosition),target=V(r.TargetPosition),budget=w.State.RemainingMarks});w.DamageCommitted+=r=>hits.Add(new{r.Step,time=w.SimulationTime,r.TargetId,r.SourceId,kind=r.Kind.ToString(),r.NormalSpeed,r.RemainingHealth,position=V(r.Position)});
for(int i=0;i<1500&&w.State.Phase==LevelPhase.Running;i++){if(i==markAt&&source>0)w.SubmitMark(source,Polarity.Model.Polarity.Positive);if(i==flipAt)w.SubmitMark(recolor,Polarity.Model.Polarity.Positive);if(i==thirdAt)w.SubmitMark(thirdTarget,Polarity.Model.Polarity.Negative);int target=-1;for(int k=0;k<switchAt.Length;k++)if(i>=switchAt[k])target=k;if(target>=0)Walk(w,destinations[target]);else w.Player.SampleMoveInput(false,false,false,false);Step(w);string pairs=string.Join(",",w.LastContactPairs.Select(p=>p.AId+"-"+p.BId));if(pairs!=lastPairs){lastPairs=pairs;contactChanges.Add(new{step=w.CompletedStepCount,pairs,p=V(w.Player.Rigidbody.position)});}if(i%25==0||w.LastPropagationResults.Count>0||w.LastDamageResults.Count>0)traces.Add(new{step=w.CompletedStepCount,p=V(w.Player.Rigidbody.position),actors=actors.Select(b=>b!=null?new{id=b.BodyId,xy=V(b.Rigidbody.position),velocity=V(b.Rigidbody.velocity),polarity=b.CurrentPolarity.ToString(),hp=b.GetComponent<Health>()!=null?b.GetComponent<Health>().CurrentHealth:0,avoid=b.GetComponent<EnemyMotor>()!=null&&b.GetComponent<EnemyMotor>().LastAvoidingObstacle}:null)});}
return new{name,source,markAt,flipAt,recolor,thirdAt,thirdTarget,destinations=destinations.Select(V),switchAt,phase=w.State.Phase.ToString(),steps=w.CompletedStepCount,time=w.SimulationTime,hp=w.PlayerHealth.CurrentHealth,enemies=w.State.ActiveEnemyCount,budget=w.State.RemainingMarks,failed=w.FailedStepCount,gmInvincible=w.GetComponent<GMManager>().Invincible,gmUnlimited=w.GetComponent<GMManager>().UnlimitedMarks,marks,spread,hits,traces,contactChanges};}
async Task<string> Run(){var runs=new List<object>();foreach(int source in new[]{1,2})foreach(var to in new[]{new Vector2(2,1),new Vector2(0,2),new Vector2(2,3),new Vector2(0,-2),new Vector2(4,-3),new Vector2(-1,1)})runs.Add(await Case("seed propagation",source,20,-1,new[]{to},new[]{0}));System.IO.File.WriteAllText("D:/Code/Polarity/docs/verification/步骤14-种子传播探索.json",JsonConvert.SerializeObject(runs));return JsonConvert.SerializeObject(runs.Select(r=>{var j=Codely.Newtonsoft.Json.Linq.JObject.FromObject(r);return new{source=j["source"],destination=j["destinations"],phase=j["phase"],time=j["time"],enemies=j["enemies"],spread=j["spread"],hits=j["hits"]};}));}return Run();

