for(int i=0;i<1500&&w.State.Phase==LevelPhase.Running;i++){if(i==markAt&&source>0)w.SubmitMark(source,Polarity.Model.Polarity.Positive);if(i==flipAt)w.SubmitMark(recolor,Polarity.Model.Polarity.Positive);if(i==thirdAt)w.SubmitMark(thirdTarget,Polarity.Model.Polarity.Negative);if(name=="zero-budget"&&i==200)w.SubmitMark(2,Polarity.Model.Polarity.Negative);int target=-1;for(int k=0;k<switchAt.Length;k++)if(i>=switchAt[k])target=k;if(target>=0)Walk(w,destinations[target]);else w.Player.SampleMoveInput(false,false,false,false);Step(w);string pairs=string.Join(",",w.LastContactPairs.Select(p=>p.AId+"-"+p.BId));if(pairs!=lastPairs){lastPairs=pairs;contactChanges.Add(new{step=w.CompletedStepCount,pairs,p=V(w.Player.Rigidbody.position),states=actors.Where(b=>b!=null).Select(b=>new{id=b.BodyId,polarity=b.CurrentPolarity.ToString(),xy=V(b.Rigidbody.position)}).ToArray()});}if(i%25==0||w.LastPropagationResults.Count>0||w.LastDamageResults.Count>0)traces.Add(new{step=w.CompletedStepCount,p=V(w.Player.Rigidbody.position),actors=actors.Select(b=>b!=null?new{id=b.BodyId,xy=V(b.Rigidbody.position),velocity=V(b.Rigidbody.velocity),polarity=b.CurrentPolarity.ToString(),hp=b.GetComponent<Health>()!=null?b.GetComponent<Health>().CurrentHealth:0,avoid=b.GetComponent<EnemyMotor>()!=null&&b.GetComponent<EnemyMotor>().LastAvoidingObstacle}:null).ToArray()});}
return new{initial,name,source,markAt,flipAt,recolor,thirdAt,thirdTarget,destinations=destinations.Select(V),switchAt,phase=w.State.Phase.ToString(),steps=w.CompletedStepCount,time=w.SimulationTime,hp=w.PlayerHealth.CurrentHealth,enemies=w.State.ActiveEnemyCount,budget=w.State.RemainingMarks,failed=w.FailedStepCount,gmInvincible=w.GetComponent<GMManager>().Invincible,gmUnlimited=w.GetComponent<GMManager>().UnlimitedMarks,marks,spread,hits,traces,contactChanges};}
async Task<string> Run(){var all=new List<object>();foreach(int turn in new[]{45,65,85,105})all.Add(await Case("recovery-after-diverge-"+turn,2,0,-1,new[]{new Vector2(6,-3),new Vector2(4,-3)},new[]{25,turn}));System.IO.File.WriteAllText("D:/Code/Polarity/docs/verification/步骤14-重新接续.json",JsonConvert.SerializeObject(all));return "saved "+all.Count;}return Run();
